# ---- Feature standardisation from training (do not modify) -------------------
# z-score with the mean/std of the TRAINING events; None = no standardisation.
FEATURE_MEAN = [0.236, 13.686000062799991, -0.004253763578225013, 416.5870784900001, 56.49704561971307, 2.942, 374.6814731470005, 566.7345907300013, 0.499, 216.09016666600016, 0.4683855444730003, 2.4559390801300034]
